'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(input[0]);
const digits = input.slice(1).join('');

function isValid(length) {
  let pos = length;
  let value = BigInt(digits.slice(0, length));

  while (pos < n) {
    value++;
    const next = value.toString();

    if (pos + next.length > n || !digits.startsWith(next, pos)) {
      return false;
    }
    pos += next.length;
  }

  return true;
}

for (let length = 1; length <= n; length++) {
  if (digits[0] !== '0' && isValid(length)) {
    console.log(digits.slice(0, length));
    break;
  }
}
